using SoulsFormats;
using System.Text.Json;
using System.Text.RegularExpressions;

static class NewHexes {
 static void Check(bool ok,string message){if(!ok)throw new InvalidDataException(message);}
 static void Set(PARAM.Row row,string field,object value){row[field].Value=Convert.ChangeType(value,row[field].Value.GetType());}
 public static void Stage(string root,BND4 original,Func<string,Memory<byte>,PARAM> parse,Hex[] hexes,string? input=null){
  string output=Path.Combine(root,".work/new-hexes-01733/staged");Directory.CreateDirectory(output);
  var binder=SFUtil.DecryptNightreignRegulation(input??Path.Combine(root,"dist/mod/regulation.bin"));
  Check(binder.Version==original.Version,"New ability source regulation version changed");
  var before=binder.Files.ToDictionary(f=>f.ID,f=>f.Bytes.ToArray());
  string[] names={"SpEffectParam","SpEffectVfxParam","AttachEffectParam","PermanentBuffParam","EquipParamGoods","ItemTableParam","ItemLotParam_enemy","BehaviorParam_PC","Bullet","AtkParam_Pc","NpcParam"};
  var tables=names.ToDictionary(n=>n,n=>parse(n,binder.Files.Single(f=>Path.GetFileName(f.Name)==n+".param").Bytes));
  var baseline=names.ToDictionary(n=>n,n=>parse(n,before[binder.Files.Single(f=>Path.GetFileName(f.Name)==n+".param").ID]));
  var changed=names.ToDictionary(n=>n,n=>new HashSet<int>());
  PARAM.Row Add(string table,int source,int id){var p=tables[table];Check(!p.Rows.Any(r=>r.ID==id),$"New ID collision: {table} {id}");var row=new PARAM.Row(p.Rows.Single(r=>r.ID==source)){ID=id};p.Rows.Add(row);changed[table].Add(id);return row;}
  foreach(var h in hexes.Where(h=>h.Id>=95001700)){
   var effect=Add("SpEffectParam",8000000,h.Id);Set(effect,"maxHpRate",h.Id==95001700?1.5f:1f);Set(effect,"spCategory",20);Set(effect,"iconId",h.SmallIcon);Set(effect,"spEffectTextId_1",h.Id);Set(effect,"displayIconForPermamentEffect",0);
   if(h.Id==95001700)foreach(string field in new[]{"slashDamageCutRate","blowDamageCutRate","thrustDamageCutRate","neutralDamageCutRate","magicDamageCutRate","fireDamageCutRate","thunderDamageCutRate","darkDamageCutRate"})Set(effect,field,field=="thrustDamageCutRate"?BalloonBalance.ThrustDamageRate:1.3f);
   var attach=Add("AttachEffectParam",95000700,h.Id);Set(attach,"passiveSpEffectId_1",h.Id);Set(attach,"passiveSpEffectId_2",-1);Set(attach,"attachTextId",h.Id);Set(attach,"statusIconId",h.SmallIcon);Set(attach,"overrideBaseEffectId",h.Id);
   var permanent=Add("PermanentBuffParam",95000700,h.Id);Set(permanent,"spEffectId",h.Id);Set(permanent,"iconId",h.LargeIcon);
   var good=Add("EquipParamGoods",95000700,h.Id);Set(good,"vagrantItemLotId",h.Id);Set(good,"iconId",h.LargeIcon-1000);
   var table=Add("ItemTableParam",95110106,95110100+Array.IndexOf(hexes,h));Set(table,"itemId",h.Id);
  }
  int privateNpcCount=AddMechanics(tables,Add,output);
  // Keep all old triples at their old lot IDs, so existing balls remain valid.
  var oldOwners=hexes.Take(15).Select(h=>h.Id).ToArray();Check(oldOwners.Length==15,"Old pool mismatch");
  var orders=new List<int[]>();
  foreach(int count in new[]{15,hexes.Length})for(int a=0;a<count;a++)for(int b=0;b<count;b++)for(int c=0;c<count;c++)if(a!=b&&a!=c&&b!=c&&(count==15||a>=15||b>=15||c>=15))orders.Add([a,b,c]);
  Check(orders.Count==hexes.Length*(hexes.Length-1)*(hexes.Length-2),"Incomplete new pool");
  for(int g=2730;g<orders.Count;g++)for(int slot=0;slot<3;slot++){var row=Add("ItemLotParam_enemy",95200000+slot,95200000+g*10+slot);Set(row,"lotItemId01",95110100+orders[g][slot]);}
  File.WriteAllText(Path.Combine(output,"hex_pool.rs"),"// Generated by HexBuild; old triples retain their native lot IDs.\n"+$"pub const HEX_COUNT: usize = {hexes.Length};\npub const OWNER_IDS: [i32; {hexes.Length}] = [{string.Join(",",hexes.Select(h=>h.Id))}];\npub const ORDERS: [[usize; 3]; {orders.Count}] = [\n"+string.Join("\n",orders.Select(o=>$" [{string.Join(",",o)}],"))+"\n];\n");
  foreach(string n in names){tables[n].Rows=tables[n].Rows.OrderBy(r=>r.ID).ToList();binder.Files.Single(f=>Path.GetFileName(f.Name)==n+".param").Bytes=tables[n].Write();}
  string destination=Path.Combine(output,"regulation.bin");SFUtil.EncryptNightreignRegulation(destination,binder,binder.Compression);
  var read=SFUtil.DecryptNightreignRegulation(destination);Check(read.Version==binder.Version&&read.Files.Count==binder.Files.Count,"Regulation binder changed");
  foreach(var member in read.Files){var intended=binder.Files.Single(f=>f.ID==member.ID);Check(member.Name==intended.Name&&member.Flags==intended.Flags&&member.Bytes.Span.SequenceEqual(intended.Bytes.Span),"Regulation readback mismatch");}
  foreach(string n in names){var table=parse(n,read.Files.Single(f=>Path.GetFileName(f.Name)==n+".param").Bytes);Check(table.Rows.Count==baseline[n].Rows.Count+changed[n].Count,"Row count mismatch");Check(table.Rows.Where(r=>!changed[n].Contains(r.ID)).Zip(baseline[n].Rows.OrderBy(r=>r.ID)).All(p=>CageAI.Same(p.First,p.Second)),"Existing rows modified: "+n);foreach(int id in changed[n])Check(CageAI.Same(tables[n].Rows.Single(r=>r.ID==id),table.Rows.Single(r=>r.ID==id)),"New row readback mismatch");}
  foreach(var member in read.Files.Where(f=>!names.Contains(Path.GetFileNameWithoutExtension(f.Name))))Check(member.Bytes.Span.SequenceEqual(before[member.ID]),"Unrelated parameter member changed");
  HexTexts.Stage(root,hexes,Path.Combine(output,"texts"),allRewards:true);
  File.WriteAllText(Path.Combine(output,"validation.json"),JsonSerializer.Serialize(new{version="0.17.33",hexes,orders=orders.Count,preservedOriginalTriples=2730,privateSpiritNpcCount=privateNpcCount,newRows=changed.ToDictionary(p=>p.Key,p=>p.Value.Order().ToArray()),existingRowsUnchanged=true,unrelatedMembersUnchanged=true,gameplayVerified=false,multiplayerVerified=false},new JsonSerializerOptions{WriteIndented=true}));
  Console.WriteLine($"PASS: staged 17 abilities, {orders.Count} triples and {privateNpcCount} private spirit NPC rows; old rows/balls preserved");
 }
 public static int AddMechanics(Dictionary<string,PARAM> tables,Func<string,int,int,PARAM.Row> Add,string output){
  Directory.CreateDirectory(output);
  // Exactly representable HavokScript action markers; no periodic mechanics.
  foreach(int id in new[]{6999900,6999901,6999902,6999910,6999911}){
   var row=Add("SpEffectParam",8000000,id);Set(row,"maxHpRate",1f);Set(row,"saveCategory",-1);Set(row,"iconId",-1);Set(row,"spEffectTextId_1",-1);Set(row,"displayIconForPermamentEffect",0);Set(row,"effectEndurance",id is 6999900 or 6999910?-1f:.001f);
  }
  var blast=Add("SpEffectParam",8630802,95001701);Set(blast,"behaviorId",950017000);Set(blast,"replaceSpEffectId",-1);Set(blast,"saveCategory",-1);Set(blast,"iconId",-1);Set(blast,"spEffectTextId_1",-1);
  // The native reward pulse is normally alive-only. A post-death explosion
  // explicitly accepts the dead PC and survives cleanup for its one-second
  // emission window; it never prevents death or becomes a permanent buff.
  Set(blast,"effectTargetPcDeceased",1);Set(blast,"dontDeleteOnDead",1);
  var behavior=Add("BehaviorParam_PC",863080000,950017000);Set(behavior,"refId",95001750);
  var bullet=Add("Bullet",12641050,95001750);Set(bullet,"atkId_Bullet",95001760);
  var attack=Add("AtkParam_Pc",12064105,95001760);
  foreach(string f in new[]{"atkPhys","atkMag","atkFire","atkThun","atkDark","atkSuperArmor"})Set(attack,f,f=="atkPhys"?1:f=="atkSuperArmor"?16.8f:0);
  Set(attack,"isAddBaseAtk",0);Set(attack,"dmgLevel",7);Set(attack,"selfTarget",0);Set(attack,"friendlyTarget",0);
  BalloonAttribute.Configure(attack,bullet);
  // Retain native Necromancy AI/death semantics with a private drain/rate.
  var drain=Add("SpEffectParam",705200,95001801);Set(drain,"changeHpRate",0f);Set(drain,"motionInterval",1f);Set(drain,"saveCategory",-1);Set(drain,"iconId",-1);Set(drain,"spEffectTextId_1",-1);
  SpiritRework.Configure(Add,drain);
  var npcSources=tables["NpcParam"].Rows.Where(r=>r.ID>=0&&r.ID is not (>=95400000 and <95500000)).OrderBy(r=>r.ID).ToArray();
  Check(npcSources.Length<100000,"Private spirit NPC range exhausted");
  for(int i=0;i<npcSources.Length;i++){
   int source=npcSources[i].ID,id=95400000+i;var npc=Add("NpcParam",source,id);
   Set(npc,"getSoul",0);Set(npc,"affectedByNecromancy",0);Set(npc,"isSoulGetByBoss",0);Set(npc,"excludeGroupRewardCheck",1);
   // Native Revenant families use player-side damage classification. Merely
   // changing allegiance leaves boss copies subject to enemy-vs-enemy cuts.
   Set(npc,"isCalculatePvPDamage",1);
   foreach(string field in new[]{"itemLotId_enemy","itemLotId_map","rewardItemLot_1","rewardItemLot_2","sleepCollectorItemLotId_enemy","sleepCollectorItemLotId_map","chaosMatchingRewardLotId","chaosMatchingItemLotId"})Set(npc,field,-1);
  }
  File.WriteAllText(Path.Combine(output,"spirit_npcs.rs"),"// Generated private NPC map. Original rows remain unchanged.\npub const NPCS: &[(i32,i32)] = &[\n"+string.Join("\n",npcSources.Select((r,i)=>$" ({r.ID},{95400000+i}),"))+"\n];\n");
  return npcSources.Length;
 }
 public static void Probe(string root,BND4 binder,Func<string,Memory<byte>,PARAM> parse,string hash){
  var output=Path.Combine(root,".work/new-hexes-01733");Directory.CreateDirectory(output);
  var all=new Dictionary<string,object>();
  foreach(string name in new[]{"SpEffectParam","Bullet","BehaviorParam_PC","AtkParam_Pc","PlayerCommonParam","NpcParam","NpcThinkParam"}){
   var table=parse(name,binder.Files.Single(f=>Path.GetFileName(f.Name)==name+".param").Bytes);
   if(name=="PlayerCommonParam")File.WriteAllBytes(Path.Combine(output,"player-common.param"),table.Write());
   IEnumerable<PARAM.Row> rows=table.Rows;
   if(name=="SpEffectParam") rows=rows.Where(r=>r.ID is >=8630800 and <=8630805 or >=102000 and <=102500 or >=705000 and <=705299 or >=103000 and <=103020 or 270000 or 271000 or 272000 or 8000000);
   else if(name=="Bullet")rows=rows.Where(r=>r.ID==12641050||r.ID is >=270000 and <=272999);
   else if(name=="BehaviorParam_PC")rows=rows.Where(r=>r.ID==863080000||r.ID is >=270000 and <=272999);
   else if(name=="AtkParam_Pc")rows=rows.Where(r=>r.ID is >=12064000 and <=12064999);
   else if(name is "NpcParam" or "NpcThinkParam")rows=rows.Where(r=>r.ID is 137030000 or 143400000 or 149610000 or 32500010);
   all[name]=rows.Select(r=>new{r.ID,fields=r.Cells.Where(c=>c!=null).ToDictionary(c=>c.Def.InternalName,c=>c.Value)}).ToArray();
  }
  File.WriteAllText(Path.Combine(output,"native-parameters.json"),JsonSerializer.Serialize(new{hash,tables=all},new JsonSerializerOptions{WriteIndented=true}));
  Console.WriteLine("Read-only golden shockwave, near-death and Revenant parameter evidence exported");
 }
}
